/**
 * Client data-layer generator (plan client-data-layer): types + services, RTK thunks and slice parts for a mobile /
 * web client. No UI.
 *
 * Per module and layer `<x>.<layer>.generated.ts` (Generator header, rewritten) + `<x>.<layer>.ts` (created once,
 * user-owned: re-exports / composes the generated file and holds custom code), and one `common.generated.ts` per
 * client. Screens keep importing `<x>.service` / `<x>.thunk` / `<x>.slice`. The root reducer is never edited: a new
 * slice comes with a note naming the lines to add.
 */
import Handlebars from 'handlebars';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
import { dirname, join } from 'path';
import type { NormalizedModel } from '../../../shared/normalizedModel.js';
import { findNormalMountPath } from '../../utils/backendAppFile.js';
import { findDotnetHost } from '../../parsers/dotnet/dotnetHost.js';
import { isGeneratorOwnedSource } from '../../utils/generatedFileOwnership.js';
import { moduleNameFromEntity } from '../../utils/namingUtils.js';
import { getTemplatesDir } from '../../utils/templateHelpers.js';
import { buildClientModuleContext, type ClientModuleContext } from './clientContext.js';
import { normalizeAuthModules, type AuthModule } from '../../../shared/authModules.js';
import { readWorkspaceManifest } from '../../utils/manifestSnapshot.js';
import type { ClientPreset } from './clientPreset.js';

export type ClientWriteAction = 'created' | 'updated' | 'unchanged' | 'skipped-user-owned' | 'skipped-exists';
export interface ClientWrittenFile {
  path: string;
  action: ClientWriteAction;
}

export interface ClientGenerateOptions {
  /** Client project root (e.g. Varlik360 `apps/mobile`). */
  clientRoot: string;
  preset: ClientPreset;
  /** Models to generate. */
  models: NormalizedModel[];
  /** Every model of the backend (relation targets); defaults to `models`. */
  allModels?: NormalizedModel[];
  /** Backend root: normal router mounts are read from its app file / endpoint files. */
  backendRoot?: string;
  /** Fallback base when a mount is not found, e.g. `/api`. */
  baseUrl?: string;
  /** The BE writes `null` for empty optional fields; default: on when `backendRoot` is a .NET host. */
  optionalAsNull?: boolean;
  /** Layers to write (default: all). A module without normal operations gets only its service types. */
  layers?: Partial<Record<ClientLayer, boolean>>;
  /** Header date (tests pin it). */
  now?: Date;
  /**
   * Shared auth layer (docs/backend/auth.md): types, service, refresh queue, token storage, thunks and slice for these
   * modules. Default: the backend manifest's `workspace.auth` (none for a host made before it).
   */
  auth?: ClientAuthOptions | false;
}

export interface ClientAuthOptions {
  modules: readonly AuthModule[];
  /** `/api` (Express, .NET) or `/api/v1` (Python). */
  prefix: string;
  /** Storage key prefix of the tokens (app name). */
  storagePrefix?: string;
}

export type ClientLayer = 'service' | 'thunk' | 'slice';

export interface ClientGenerateResult {
  files: ClientWrittenFile[];
  modules: ClientModuleContext[];
  warnings: string[];
  /** Things the user does by hand (root reducer registration). */
  notes: string[];
}

const HEADER = '// Auto Generated By Generator';

function formatDate(date: Date): string {
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${pad(date.getDate())}.${pad(date.getMonth() + 1)}.${date.getFullYear()} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
}

const templateCache = new Map<string, HandlebarsTemplateDelegate>();

function render(name: string, data: unknown): string {
  let template = templateCache.get(name);
  if (!template) {
    template = Handlebars.compile(readFileSync(join(getTemplatesDir('client-redux'), `${name}.hbs`), 'utf8'), { noEscape: true });
    templateCache.set(name, template);
  }
  return template(data);
}

function write(path: string, content: string): void {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content, 'utf8');
}

/** Body without the header line: a regenerate that only moves the date leaves the file alone. */
const body = (content: string) => content.slice(content.indexOf('\n') + 1);

/** G file: rewritten when its body changes; a file without the Generator header is user-owned and left alone. */
function writeGenerated(path: string, content: string): ClientWrittenFile {
  if (!existsSync(path)) {
    write(path, content);
    return { path, action: 'created' };
  }
  const current = readFileSync(path, 'utf8');
  if (!isGeneratorOwnedSource(current)) return { path, action: 'skipped-user-owned' };
  if (body(current) === body(content)) return { path, action: 'unchanged' };
  write(path, content);
  return { path, action: 'updated' };
}

/** K file: created when missing, never overwritten. */
function writeOnce(path: string, content: string): ClientWrittenFile {
  if (existsSync(path)) return { path, action: 'skipped-exists' };
  write(path, content);
  return { path, action: 'created' };
}

function commonImports(ctx: ClientModuleContext): string {
  // Type-only names marked `type` (hosts with `verbatimModuleSyntax`).
  const types = ctx.ops.list ? ['ListPaginationBody', 'PaginatedList'] : [];
  return [...types, 'RequestOptions'].map(name => `type ${name}`).concat('requestFlags').join(', ');
}

/** Template data of one module: the context plus names derived for the thunk / slice templates. */
function templateData(ctx: ClientModuleContext, header: string) {
  const { entity, ops, names } = ctx;
  const hasWrites = ops.create || ops.update;
  const hasSaved = ctx.savedProps !== undefined && hasWrites;
  const thunks = {
    list: `fetch${entity}List`,
    getOne: `fetch${entity}ById`,
    create: `create${entity}`,
    update: `update${entity}`,
    delete: `delete${entity}`
  };
  const serviceTypes = [
    ops.list || ops.getOne ? names.row : null,
    hasWrites ? names.saved : null,
    ops.create ? names.createInput : null,
    ops.update ? names.updateInput : null,
    ops.list ? names.listBody : null
  ].filter((n): n is string => n !== null);
  const sliceTypes = [names.row, ...(hasSaved ? [names.saved] : [])];
  return {
    ...ctx,
    header,
    hasWrites,
    hasReads: ops.list || ops.getOne,
    /** Separate `I<E>Saved` interface (populated relations come back as ids). */
    hasSavedType: hasSaved,
    commonImports: commonImports(ctx),
    thunks,
    thunkList: ctx.surface.operations.map(op => thunks[op]).join(', '),
    requestOptionKeys: ctx.surface.operations.map(op => `${op}?: RequestOptions`).join('; '),
    serviceTypeImports: [...new Set(serviceTypes)].join(', '),
    sliceTypeImports: sliceTypes.join(', '),
    populateHelpers: [
      ...(ctx.populatedRefs.some(r => !r.isArray) ? ['keepPopulated'] : []),
      ...(ctx.populatedRefs.some(r => r.isArray) ? ['keepPopulatedAll'] : [])
    ].join(', ')
  };
}

export function generateClientModules(options: ClientGenerateOptions): ClientGenerateResult {
  const { clientRoot, preset, models, backendRoot } = options;
  const allModels = options.allModels ?? models;
  const header = `${HEADER} - ${formatDate(options.now ?? new Date())}`;
  const servicesDir = join(clientRoot, preset.dirs.services);
  const layer = (l: ClientLayer) => options.layers?.[l] !== false;
  const warnings: string[] = [];
  const notes: string[] = [];
  const optionalAsNull = options.optionalAsNull ?? (backendRoot ? findDotnetHost(backendRoot) !== null : false);
  const files: ClientWrittenFile[] = [];
  const modules: ClientModuleContext[] = [];

  files.push(writeGenerated(join(servicesDir, 'common.generated.ts'), render('common.generated.ts', { header, headers: preset.requestFlags === 'headers' })));

  for (const model of models) {
    const moduleName = moduleNameFromEntity(model.entityName);
    let endpoint = backendRoot ? findNormalMountPath(backendRoot, moduleName) : null;
    if (!endpoint) {
      endpoint = `${(options.baseUrl || '/api').replace(/\/+$/, '')}/${moduleName}`;
      if (model.api?.normalOperations?.length !== 0) {
        warnings.push(`${model.entityName}: normal route not found in the backend; using ${endpoint}`);
      }
    }
    const ctx = buildClientModuleContext({ model, models: allModels, endpoint, preset, optionalAsNull });
    modules.push(ctx);
    if (ctx.surface.dropped.length) {
      warnings.push(`${model.entityName}: closed by the contract, not generated: ${ctx.surface.dropped.join(', ')}`);
    }
    const data = templateData(ctx, header);
    if (layer('service')) {
      files.push(writeGenerated(join(servicesDir, `${ctx.camel}.service.generated.ts`), render('service.generated.ts', data)));
      files.push(writeOnce(join(servicesDir, `${ctx.camel}.service.ts`), render('service.ts', data)));
    }
    // Thunks / slice only over generated operations (a module with custom endpoints only keeps its own).
    if (!ctx.hasOps) continue;
    const thunkFile = join(clientRoot, preset.dirs.thunks, `${ctx.camel}.thunk.ts`);
    if (layer('thunk')) {
      files.push(writeGenerated(join(clientRoot, preset.dirs.thunks, `${ctx.camel}.thunk.generated.ts`), render('thunk.generated.ts', data)));
      files.push(writeOnce(thunkFile, render('thunk.ts', data)));
    }
    if (layer('slice') && layer('thunk')) {
      const dir = join(clientRoot, preset.dirs.slices);
      files.push(writeGenerated(join(dir, `${ctx.camel}.slice.generated.ts`), render('slice.generated.ts', data)));
      const sliceFile = join(dir, `${ctx.camel}.slice.ts`);
      // The created-once slice builds on `<x>Thunks` of the user's thunk file; an older thunk file does not have it.
      if (!existsSync(sliceFile) && !(existsSync(thunkFile) && new RegExp(`\\b${ctx.camel}Thunks\\b`).test(readFileSync(thunkFile, "utf8")))) {
        warnings.push(`${ctx.entity}: ${ctx.camel}.slice.ts oluşturulmadı: ${ctx.camel}.thunk.ts \`${ctx.camel}Thunks\` vermiyor (create${ctx.entity}Thunks ile kur)`);
        continue;
      }
      const slice = writeOnce(sliceFile, render('slice.ts', data));
      files.push(slice);
      if (slice.action === 'created') {
        notes.push(
          `${ctx.entity}: root reducer'a ekle → import ${ctx.camel}Reducer from '${preset.imports.rootState}/slices/${ctx.camel}.slice'; ` +
            `rootReducer içine ${ctx.camel}: ${ctx.camel}Reducer`
        );
      }
    }
  }
  const auth = options.auth === false ? null : (options.auth ?? (backendRoot ? clientAuthFromManifest(backendRoot) : null));
  if (auth) files.push(...generateClientAuth(clientRoot, preset, auth, header, notes));
  return { files, modules, warnings, notes };
}

/** `workspace.auth` of the backend manifest → what the client generates; `null` for a host without the auth layer. */
export function clientAuthFromManifest(backendRoot: string): ClientAuthOptions | null {
  const workspace = readWorkspaceManifest(backendRoot)?.workspace;
  if (!workspace?.auth) return null;
  return { modules: normalizeAuthModules(workspace.auth.modules), prefix: workspace.backendStack === 'python-fastapi' ? '/api/v1' : '/api' };
}

/** G files of the shared auth layer; UI stays in the host (login / register screens). */
function generateClientAuth(clientRoot: string, preset: ClientPreset, auth: ClientAuthOptions, header: string, notes: string[]): ClientWrittenFile[] {
  const has = (m: AuthModule) => auth.modules.includes(m);
  const purposes = [...(has('register') ? ["'verify'"] : []), ...(has('password-reset') ? ["'reset'"] : [])];
  const data = {
    header,
    imports: preset.imports,
    thunksImport: `${preset.imports.rootState}/thunks`,
    headers: preset.requestFlags === 'headers',
    asyncStorage: preset.tokenStorage === 'async-storage',
    storagePrefix: (auth.storagePrefix ?? 'app').toLowerCase().replace(/[^a-z0-9]+/g, '_'),
    prefix: auth.prefix.replace(/\/+$/, ''),
    moduleList: auth.modules.length ? auth.modules.join(', ') : 'core only',
    register: has('register'),
    passwordReset: has('password-reset'),
    otp: purposes.length > 0,
    otpPurposes: purposes.join(' | '),
    google: has('google'),
    apple: has('apple'),
    // A Google / Apple account has no password until it creates one (`set-password`).
    social: has('google') || has('apple'),
    accountDelete: has('account-delete')
  };
  const servicesDir = join(clientRoot, preset.dirs.services);
  const files = [
    writeGenerated(join(servicesDir, 'auth.service.generated.ts'), render('auth.service.generated.ts', data)),
    writeGenerated(join(servicesDir, 'authStorage.generated.ts'), render('authStorage.generated.ts', data)),
    writeGenerated(join(servicesDir, 'authRefresh.generated.ts'), render('authRefresh.generated.ts', data)),
    writeGenerated(join(clientRoot, preset.dirs.thunks, 'auth.thunk.generated.ts'), render('auth.thunk.generated.ts', data)),
    writeGenerated(join(clientRoot, preset.dirs.slices, 'auth.slice.generated.ts'), render('auth.slice.generated.ts', data))
  ];
  if (files.some((f) => f.action === 'created')) {
    notes.push(
      `Auth: root reducer'a auth: authReducer (${preset.imports.rootState}/slices/auth.slice.generated), store kurulunca bindAuthStore(store); ` +
        `api.ts interceptor'ı 401'de (isAuthRequest değilse) refreshSessionOnce() → true ise isteği bir kez tekrarlar; Authorization = state.auth.accessToken`
    );
  }
  return files;
}
